// v2 — F1: filtra records vacíos antes de procesar.
// Cuando el Search no encuentra match, Airtable con alwaysOutputData devuelve [{}]
// y el v1 anterior decía "Encontré undefined en el catálogo".

const matches = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id && r['Insumo']);
const args = $('Execute Workflow Trigger').first().json;
const URL_TIENDA = "https://www.sistemasysoluciones.com";

// Si no hay match real, o no hay producto ni categoría pasados, devolvemos URL general.
if (matches.length === 0 || (!args.producto && !args.categoria)) {
  return [{ json: {
    status: 'RESOLVED',
    data: {
      url_general: URL_TIENDA,
      url_categoria: null,
      url_producto_especifico: null,
      producto_referencia: null,
      mensaje_sugerido_agente: `Podés ver y comprar insumos online en ${URL_TIENDA}. Si necesitás ayuda para elegir, te paso con el equipo.`
    },
    trace_id: $execution.id
  } }];
}

const primer = matches[0].json;
const urlEspecifica = primer['URL tienda'] || null;
return [{ json: {
  status: 'RESOLVED',
  data: {
    url_general: URL_TIENDA,
    url_categoria: null,
    url_producto_especifico: urlEspecifica,
    producto_referencia: primer['Insumo'] || '',
    mensaje_sugerido_agente: urlEspecifica
      ? `Encontré ${primer['Insumo']}. Link directo: ${urlEspecifica}. También podés ver el catálogo general en ${URL_TIENDA}.`
      : `Encontré ${primer['Insumo']} en el catálogo. Para verlo: ${URL_TIENDA}. Si querés que alguien te ayude, te paso con el equipo.`
  },
  trace_id: $execution.id
} }];
